#include <windows.h>
#include <stdio.h>

int main() {
    SC_HANDLE manager = OpenSCManagerA(nullptr, nullptr,
        SC_MANAGER_CONNECT);
    SC_HANDLE service = OpenServiceA(manager, "Spooler",
        SERVICE_QUERY_STATUS);
    if (service == nullptr) {
        CloseServiceHandle(manager);
        return 1;
    }

    SERVICE_STATUS status = {};
    if (ControlService(service, SERVICE_CONTROL_INTERROGATE, &status)) {
        printf("Service state: %lu\n", status.dwCurrentState);
    }

    CloseServiceHandle(service);
    CloseServiceHandle(manager);
    return 0;
}

#include <windows.h>
#include <stdio.h>

int main() {
    SC_HANDLE manager = OpenSCManagerA(nullptr, nullptr,
        SC_MANAGER_CONNECT);
    SC_HANDLE service = OpenServiceA(manager, "Spooler",
        SERVICE_QUERY_STATUS);
    if (service == nullptr) {
        CloseServiceHandle(manager);
        return 1;
    }

    SERVICE_STATUS status = {};
    if (ControlServiceExA(service, SERVICE_CONTROL_INTERROGATE,
            SERVICE_CONTROL_STATUS_REASON_INFO, &status)) {
        printf("Service state: %lu\n", status.dwCurrentState);
    }

    CloseServiceHandle(service);
    CloseServiceHandle(manager);
    return 0;
}

